import{_ as s,o as t,c as r,a3 as o}from"./chunks/framework.C9yOUAca.js";const m=JSON.parse(`{"title":"The server's schema is SQLDelight migrations on Postgres, applied on start","description":"","frontmatter":{"status":"accepted","date":"2026-11-07T00:00:00.000Z"},"headers":[],"relativePath":"docs/adr/0022-the-servers-schema-is-sqldelight-migrations-on-postgres.md","filePath":"docs/adr/0022-the-servers-schema-is-sqldelight-migrations-on-postgres.md"}`),a={name:"docs/adr/0022-the-servers-schema-is-sqldelight-migrations-on-postgres.md"};function n(i,e,h,d,l,c){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="the-server-s-schema-is-sqldelight-migrations-on-postgres-applied-on-start" tabindex="-1">The server&#39;s schema is SQLDelight migrations on Postgres, applied on start <a class="header-anchor" href="#the-server-s-schema-is-sqldelight-migrations-on-postgres-applied-on-start" aria-label="Permalink to &quot;The server&#39;s schema is SQLDelight migrations on Postgres, applied on start&quot;">​</a></h1><p>The server keeps its own Postgres schema (<a href="./0007-postgres-columns-for-structure-jsonb-for-content">ADR 0007</a>), separate from the phone&#39;s SQLite one: phones and the server store different things (the server has accounts and tokens, the phone has no owner column), and sync exchanges documents, not tables. Both are written the same way, though: numbered SQLDelight migrations (<code>.sqm</code>) and typed queries (<code>.sq</code>), in <code>server/src/main/sqldelight</code> for the server. The server applies the migrations it lacks every time it starts, before it answers.</p><h2 id="how-migrations-run" tabindex="-1">How migrations run <a class="header-anchor" href="#how-migrations-run" aria-label="Permalink to &quot;How migrations run&quot;">​</a></h2><ul><li><strong>The schema comes from the migrations.</strong> <code>1.sqm</code> moves version 1 to 2, <code>2.sqm</code> 2 to 3, and so on; a new database runs them all in order. A change is always a new file, never an edit of one already merged, because production has run it.</li><li><strong>The database records its version</strong> in the <code>schema_version</code> table. On start, <code>Database.migrate</code> reads it and runs the missing files in one transaction, under a Postgres advisory lock. A failed migration rolls back and stops the server, and Docker restarts it, so it never serves a half-migrated schema.</li><li><strong>A database newer than the server stops it.</strong> Rolling back to an older release after a migration means restoring the dump taken before it (<a href="./../deploying-the-server#backups">Deploying the server</a>).</li><li><strong>Tests run on a real Postgres 17</strong>, the same major version as production, started from binaries by <code>embedded-postgres</code>, so they need no Docker.</li></ul><h2 id="considered-options" tabindex="-1">Considered options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered options&quot;">​</a></h2><ul><li><strong>Flyway with plain SQL files.</strong> The usual JVM migration runner, with its own locking and history table. It would mean a second tool beside SQLDelight, and queries written by hand over JDBC with nothing checking them at build time. SQLDelight&#39;s runner is the twenty lines of <code>Database.migrate</code>.</li><li><strong>One schema shared with the phone.</strong> The tables differ too much: every server row has an owner, and the phone keeps state the server never sees.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>A schema change on the server is a new <code>.sqm</code> file, as on the phone, and its queries fail the build when they no longer match the schema.</li><li>SQLDelight&#39;s <code>verifyMigrations</code> only checks SQLite, so the server&#39;s migrations are checked by running them in the tests instead.</li></ul>',8)])])}const u=s(a,[["render",n]]);export{m as __pageData,u as default};
